def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    up = down = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and grid[p[0]][p[1]] == 2 and p not in seen:
                        seen.add(p)
                        q.append(p)
            if len(cells) != 4:
                raise ValueError(f'Expected 4-cell T, got component of {len(cells)}')
            rows = [y for y, x in cells]
            cols = [x for y, x in cells]
            # T shapes in the stream have a horizontal three-cell bar and one stem cell.
            if max(rows) - min(rows) != 1 or max(cols) - min(cols) != 2:
                raise ValueError('Unexpected T orientation')
            bar_row = next(y for y in set(rows) if sum(1 for yy, xx in cells if yy == y) == 3)
            stem_row = next(y for y in set(rows) if y != bar_row)
            if stem_row < bar_row:
                up += 1
            else:
                down += 1
    out = [[0] * 6 for _ in range(3)]
    slots = ((0, 0), (0, 2), (2, 0), (2, 2))
    for i in range(up):
        if i >= len(slots):
            raise ValueError('Too many upward T shapes for output encoding')
        y, x = slots[i]
        out[y][x] = 3
    for i in range(down):
        if i >= len(slots):
            raise ValueError('Too many downward T shapes for output encoding')
        y, x = slots[i]
        out[y][x + 3] = 1
    return out
