                        seen.add(p)
                        q.append(p)
            if len(cells) != 4:
                raise ValueError('Expected four-cell T objects')
            row_counts = {}
            for y, x in cells:
                row_counts[y] = row_counts.get(y, 0) + 1
            bar = next(y for y, n in row_counts.items() if n == 3)
            stem = next(y for y, n in row_counts.items() if n == 1)
